public static int findKthSmallestDivisible(int N, int M, int K) {
    int count = 0;
    int number = 1;

    while (true) {
        boolean divisibleByN = (number % N == 0);
        boolean divisibleByM = (number % M == 0);

        if (divisibleByN ^ divisibleByM) { // XOR to check if divisible by exactly one
            count++;
            if (count == K) {
                return number;
            }
        }
        number++;
    }
}
